function countPairsInBand(nums: number[], lower: number, upper: number): number {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const s = nums[i] + nums[j];
      if (s >= lower && s <= upper) count++;
    }
  }
  return count;
}

