function countPairsInBand(nums: number[], lower: number, upper: number): number {
  const a = [...nums].sort((x, y) => x - y);
  // first index in [from, n) whose value is >= target
  const firstAtLeast = (from: number, target: number): number => {
    let lo = from, hi = a.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[mid] < target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  let count = 0;
  for (let i = 0; i < a.length; i++) {
    count += firstAtLeast(i + 1, upper - a[i] + 1) - firstAtLeast(i + 1, lower - a[i]);
  }
  return count;
}

