function countPairsInBand(nums: number[], lower: number, upper: number): number {
  const a = [...nums].sort((x, y) => x - y);
  const atMost = (t: number): number => {
    let l = 0, r = a.length - 1, count = 0;
    while (l < r) {
      if (a[l] + a[r] <= t) {
        count += r - l; // a[l] pairs with every index in (l, r]
        l++;
      } else {
        r--;
      }
    }
    return count;
  };
  return atMost(upper) - atMost(lower - 1);
}

